const e="mdc-high-school-talent-battle",c=2023,t="Captured from the 3-page 2023 info sheet. There is no rulebook beyond the sheet, so all dates, venue, fees, prizes and contacts are 2023 facts kept as Variables. The sheet prints no time limit, no entry limit per school and no ranks or grades.",o={Title:"Rules & Criteria",Subtitle:"M.D.C High School Talent Battle (Music-Dance-Culture). Read these rules before you register.",NoticeTitle:"Please Read Before Registering",Notice:"Applications close on {{ApplicationDeadline}}. The live show is on {{EventDate}} at {{Venue}}. Entry is not guaranteed on application.",Notes:["Apply as soon as you can. Places are strictly limited.","The time sheet could change on the night."],Sections:[{Key:"general",Title:"About the Event",Items:["You enter to represent yourself and your school.","The event was created by the Melton FReeZA committees 3337 Production in partnership with Melton Young Communities. It gives young people in the community a platform and is hosted by young people.","It is a chance to show your talent to a live audience and a panel of judges. It aims to be a first step for singers, rappers and bands.","All performances are live.","The event is supervised and is a drug and alcohol free zone.","You may sing any style you are comfortable with, for example contemporary classical, Hip Hop, R&B, Pop or Urban Rock. Original songs are welcome.","The organisers encourage you to invite school friends, friends outside school and family to watch.","Audience tickets are {{AudienceTicketPrice}}. Tickets are limited and must be bought online before they sell out."]},{Key:"eligibility",Title:"Eligibility",Items:["You must be in high school.","You must be 12 to 18 years of age.","Contestants must be unsigned and must not make a living wage from performing.","Contestants under 18 must have a parent or guardian attend the event.","Contestants with cold or flu-like symptoms must show a negative RAT test result on arrival, at their own cost."]},{Key:"registration",Title:"How to Register",Items:["Record a video audition. It can be from a past performance or a simple recording at home or school.","Email the video audition to {{EntryEmailLink}}.","Nominate two song options. The organising team will choose or recommend one for you to perform live.","Complete the online application form and email it to {{EntryEmailLink}}.","Applications close on {{ApplicationDeadline}}.","The team reviews applications as they come in, so apply early."]},{Key:"levels",Title:"Stages",Items:["Stage 1 is the video audition. The team reviews all video auditions and selects contestants for the live performances.","Entry to the competition is not guaranteed on application.","Stage 2 is the live performance. Successful contestants perform live in front of a panel of judges and an audience on {{EventDate}}.","Stage 3 is judging on the night. Judges vote for the winner by scoring.","The organisers may add or reduce the number of stages and contestants at any time."]},{Key:"fees",Title:"Fees",Items:["The show fee is {{EntryFee}}. It includes competition entry.","The show fee is not refundable. It may be transferred to another season at the sole discretion of the organisers."]},{Key:"dates",Title:"Dates and Times",Items:["Applications close on {{ApplicationDeadline}}.","The competition is on {{EventDate}} for all divisions. The show runs between 7:00 pm and 9:00 pm.","Sound check: {{SoundCheckTime}}.","Doors open at {{DoorsOpenTime}}.","The show: {{ShowTime}}.","Live DJ: {{LiveDjTime}}. The dance floor is open to everyone.","The event finishes at {{FinishTime}} and everyone must leave the venue.","The time sheet could change on the night.","The organisers may change the dates and times of the event for any reason."]},{Key:"venue",Title:"Venue",Items:["The venue is {{Venue}}."]},{Key:"judging",Title:"Judging",Items:["A panel of judges scores each live performance.","Each performance is scored out of 40 on four criteria, each out of 10: Vocals, Song Choice, Performance and Audience Engagement. For example, 8 on each criterion gives a total of 32 out of 40.","The judges' decision is final.","Audience voting will not disrupt the fair nature of the scoring."]},{Key:"prizes",Title:"Prizes",Items:["On the night the winner receives a certificate, a trophy and a gift card.","1st place: {{FirstPrize}}.","2nd place: {{SecondPrize}}.","3rd place: {{ThirdPrize}}."]},{Key:"conduct",Title:"Conduct and Songs",Items:["Your song must not contain explicit language.","Your song must be right for the age range of your competition.","Choose a song that will entertain your audience."]},{Key:"other",Title:"Media Release and Confidentiality",Items:["Media release: you give permission to the organiser and partners such as FReeZA and Young Communities to use your name and image in any way related to the singing competition or the general use of the event.","You understand that any part of the production may be filmed and photographed, and you allow the recordings to be used in all media, including print, broadcast, radio and social media, during or after the production.","Confidentiality: you agree to keep confidential everything about the organiser and the competition, including conversations in person or online, contracts or documents, music materials and intellectual property.","For questions, contact {{OrganiserContact}} or {{YoungCommunitiesContact}}."]}],Documents:[{Title:"Competition info sheet (PDF)",Url:"https://sfcc.vic.edu.au/files/Newsletter/MDC-High-School-Talent-battle-competition-info.pdf"}]},n=[],i=[],a=[{Title:"Singing",Source:"Info sheet p.1-2 (FAQ: What should I sing; Do I ever have to perform live)",Sections:{About:null,TimeAndFormat:null,Rules:["Nominate two song options when you apply. The organising team chooses or recommends one for you to perform live.","All performances are live."],Allowed:null,NotAllowed:["Songs with explicit language."],Judging:["Scored out of 40: Vocals, Song Choice, Performance and Audience Engagement, each out of 10."],Points:null,Notes:null},Markdown:`## Rules
- Nominate two song options when you apply. The organising team chooses or recommends one for you to perform live.
- All performances are live.

## Not allowed
- Songs with explicit language.

## Judging
- Scored out of 40: Vocals, Song Choice, Performance and Audience Engagement, each out of 10.`}],s=[],r=[{Key:"EventDate",Kind:"date",Label:"Competition date",Value:"2023-06-16",Source:"Info sheet p.1 (Friday, June 16th, 2023)"},{Key:"ApplicationDeadline",Kind:"date",Label:"Applications close",Value:"2023-05-30",Source:"Info sheet p.1 (Applications close 30th May 2023)"},{Key:"SoundCheckTime",Kind:"time",Label:"Sound check",Value:"5:00 pm - 6:00 pm",Source:"Info sheet p.1 time sheet"},{Key:"DoorsOpenTime",Kind:"time",Label:"Doors open",Value:"6:00 pm",Source:"Info sheet p.1 time sheet"},{Key:"ShowTime",Kind:"time",Label:"Show starts",Value:"7:00 pm - 9:00 pm",Source:"Info sheet p.1 time sheet"},{Key:"LiveDjTime",Kind:"time",Label:"Live DJ (dance floor open to everyone)",Value:"9:00 pm - 10:00 pm",Source:"Info sheet p.1 time sheet"},{Key:"FinishTime",Kind:"time",Label:"Event finish",Value:"10:00 pm",Source:"Info sheet p.1 time sheet"},{Key:"Venue",Kind:"address",Label:"Event venue",Value:{Name:"Melton Town Hall (200 seats)",Address:"232 High Street",City:"Melton, Victoria, Australia",MapUrl:"",Directions:""},Source:"Info sheet p.1-2 (Venue)"},{Key:"EntryFee",Kind:"fee",Label:"Show fee (includes competition entry)",Value:"$10",Source:"Info sheet p.2 (How much is the competition)"},{Key:"AudienceTicketPrice",Kind:"fee",Label:"Audience tickets",Value:"From $10",Source:"Info sheet p.2"},{Key:"FirstPrize",Kind:"prize",Label:"1st place",Value:"$350",Source:"Info sheet p.2 (Prizes)"},{Key:"SecondPrize",Kind:"prize",Label:"2nd place",Value:"$250",Source:"Info sheet p.2 (Prizes)"},{Key:"ThirdPrize",Kind:"prize",Label:"3rd place",Value:"$50",Source:"Info sheet p.2 (Prizes)"},{Key:"EntryEmailLink",Kind:"link",Label:"Where to send the video audition and application form",Value:"melton.vic.gov.au/MDC",Source:"Info sheet p.1 (How to enter)"},{Key:"OrganiserContact",Kind:"contact",Label:"Contact person",Value:{Name:"Cyrus",Role:"Contact person",Phone:"0499 305 696",WhatsApp:"",Email:"cyrusm@melton.vic.gov.au"},Source:"Info sheet p.3 (Contact Person)"},{Key:"YoungCommunitiesContact",Kind:"contact",Label:"Melton Young Communities",Value:{Name:"Melton Young Communities",Role:"General enquiries",Phone:"",WhatsApp:"",Email:"youngcommunities@melton.vic.gov.au"},Source:"Info sheet p.3"},{Key:"Announcements",Kind:"news",Label:"News printed in the info sheet",Value:[{Date:"",Title:"Apply early",Text:"It is highly recommended to apply as soon as possible. Places are strictly limited and the team reviews applications as they come in.",Url:""},{Date:"",Title:"Time sheet may change",Text:"The time sheet could change on the night.",Url:""}],Source:"Info sheet p.1"}],l=[{Claim:"Rules, eligibility, registration steps, fees, dates, venue, prizes and terms are taken from the organiser's own info sheet for the 2023 edition.",SourceType:"Primary - the event's own rules document",Source:"M.D.C High School Talent Battle 2023 info sheet",Url:"https://sfcc.vic.edu.au/files/Newsletter/MDC-High-School-Talent-battle-competition-info.pdf"}],u={TemplateKey:e,Year:2023,Note:t,Page:o,ParticipantTypes:n,AgeGroups:i,Competitions:a,CompetitionAgeGroups:s,Variables:r,Evidence:l};export{i as AgeGroups,s as CompetitionAgeGroups,a as Competitions,l as Evidence,t as Note,o as Page,n as ParticipantTypes,e as TemplateKey,r as Variables,c as Year,u as default};
